update public.ingredient_master im set
 name_zh_cn=e.name_zh_cn,
 functions=e.functions,
 ingredient_family=e.ingredient_family,
 plain_language_zh=e.plain_language_zh,
 plain_language_en=e.plain_language_en,
 evidence_level='cosmetic_function',
 mapping_status='mapped',
 updated_at=now()
from enrichment e where im.id=e.id;

-- Resolve common INCI synonyms to an existing canonical entry instead of duplicating it.
insert into public.ingredient_master_aliases(ingredient_master_id,alias,normalized_alias,alias_type,source_count)
values
